#!/usr/bin/env python3
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'site'
BASE='/dc-public-realm'

home=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Diplomatic Gifts in Washington</title><link rel="stylesheet" href="{BASE}/assets/style.css"><style>.hero{{max-width:800px;margin:2rem 0}}.hero h1{{margin-bottom:.7rem}}.project{{border-left:4px solid #5a3d16;background:#fffdf8;padding:1rem 1.2rem;margin:2rem 0}}.project h2{{margin-top:.2rem}}.actions{{margin:1.2rem 0}}.actions .button{{margin-bottom:.5rem}}</style></head><body><header><div class="kicker">Diplomatic Gifts in Washington · research alpha</div><nav><a href="{BASE}/">Home</a><a href="{BASE}/objects/jose-gervasio-artigas/">Artigas</a><a href="{BASE}/collaborate/artigas/">Collaborate</a><a href="{BASE}/methodology/">Methodology</a></nav></header><main><section class="hero"><div class="kicker">PUBLIC ART · DIPLOMATIC HISTORY</div><h1>Diplomatic Gifts in Washington</h1><p class="lede">This project documents diplomatic monuments in Washington, D.C., and the records of their creation, presentation, fabrication, and installation.</p><p>Each record links specific historical or attribution statements to supporting, qualifying, or conflicting sources. Unresolved questions remain identified as unresolved.</p></section><section class="project"><div class="kicker">CURRENT PROJECT · URUGUAY</div><h2>José Gervasio Artigas Memorial</h2><p>U.S. and Uruguayan records document the memorial's presentation and connect the Washington bronze to an earlier Artigas monument in Uruguay. Published records differ on the predecessor monument and the fabrication history of the Washington bronze.</p><div class="actions"><a class="button" href="{BASE}/objects/jose-gervasio-artigas/">Artigas record</a><a class="button" href="{BASE}/collaborate/artigas/">Open research tasks</a><a class="button" href="{BASE}/review/artigas/">Review summary</a></div></section><section><h2>How to use this site</h2><p>Object pages present the current catalog record. Source panels show the records associated with individual statements. When sources disagree, the disagreement remains visible rather than being combined into a single account.</p><p>The <a href="{BASE}/methodology/">methodology</a> defines evidence and publication rules. Collaboration pages list records that have not yet been located or reviewed. The <a href="https://github.com/danielastone/dc-public-realm">repository</a> contains the underlying data and documentation.</p></section><section><h2>Other records</h2><div class="grid"><article class="card"><div class="kicker">ARGENTINA</div><h3><a href="{BASE}/objects/jose-de-san-martin/">José de San Martín</a></h3><p>Washington monument to José de San Martín. Current research includes attribution and object history.</p></article><article class="card"><div class="kicker">CUBA</div><h3><a href="{BASE}/objects/cuban-american-friendship-urn/">Cuban-American Friendship Urn</a></h3><p>Research record for the urn's object history and diplomatic context.</p></article></div></section></main><footer>Research is ongoing. Records may change when additional sources are reviewed.</footer></body></html>'''

collab=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Artigas Memorial Research Tasks</title><link rel="stylesheet" href="{BASE}/assets/style.css"><style>.ask{{border-left:4px solid #7a3e00;background:#fffdf8;padding:1rem;margin:1rem 0}}.small{{font-family:ui-sans-serif,system-ui,sans-serif;color:#666;font-size:.9rem}}</style></head><body><header><div class="kicker">Diplomatic Gifts in Washington · research</div><nav><a href="{BASE}/">Home</a><a href="{BASE}/objects/jose-gervasio-artigas/">Artigas record</a><a href="{BASE}/review/artigas/">Review</a></nav></header><main><div class="kicker">JOSÉ GERVASIO ARTIGAS MEMORIAL</div><h1>Open Research Tasks</h1><p class="lede">These tasks identify records needed to clarify the fabrication history of the Washington memorial and the sources used in later institutional catalogs.</p><h2>Smithsonian source records</h2><p>The Smithsonian inventory cites the following research sources without assigning them to individual statements. The immediate task is to locate the cited material and record what it supports.</p><article class="ask"><h3>Goode (1974), pp. 443–444</h3><p><strong>Request:</strong> Locate the Artigas entry and its citations, notes, or acknowledgments.</p><a class="button" href="https://github.com/danielastone/dc-public-realm/issues/19">Task details</a></article><article class="ask"><h3>Michael Richman, 1967–69</h3><p><strong>Request:</strong> Locate the collection, folder, finding aid, or research notes cited by the Smithsonian inventory.</p><a class="button" href="https://github.com/danielastone/dc-public-realm/issues/20">Task details</a></article><article class="ask"><h3>National Park Service, 1985</h3><p><strong>Request:</strong> Identify the cited NPS record and any references associated with it.</p><a class="button" href="https://github.com/danielastone/dc-public-realm/issues/21">Task details</a></article><article class="ask"><h3>Smithsonian research project, 1991</h3><p><strong>Request:</strong> Locate project documentation that identifies the records consulted and statements recorded.</p><a class="button" href="https://github.com/danielastone/dc-public-realm/issues/22">Task details</a></article><h2>Additional records</h2><article class="ask"><h3>Uruguay, 1894–1896</h3><p><strong>Request:</strong> Locate the commission and contract records concerning Juan Luis Blanes, Juan Manuel Blanes, and Dante Costa that underlie later descriptions of the San José monument.</p><p class="small">Useful material: archival citations, catalog records, digital images, or authoritative reproductions.</p></article><article class="ask"><h3>Uruguay and the United States, approximately 1947–1951</h3><p><strong>Request:</strong> Locate diplomatic, fabrication, shipping, dedication, or installation records concerning the Washington bronze.</p></article><h2>Submit information</h2><p>Submit a correction, archival citation, finding-aid reference, scan, or collection reference through the linked research task. A submission does not change the public record. The source is reviewed first; accepted evidence is then added to the record.</p><p>When reliable records disagree, both records remain documented until additional evidence resolves the difference.</p><p><a class="button" href="{BASE}/objects/jose-gervasio-artigas/">Artigas record</a><a class="button" href="{BASE}/review/artigas/">Review summary</a></p></main><footer>Open tasks identify research needs; they are not evidence until the cited material is reviewed.</footer></body></html>'''

(SITE/'index.html').write_text(home,encoding='utf-8')
d=SITE/'collaborate'/'artigas'; d.mkdir(parents=True,exist_ok=True); (d/'index.html').write_text(collab,encoding='utf-8')
print('Updated project pages with technical-writing structure')
